<?php

declare(strict_types=1);

namespace Ithilgers\ApiExport\Feed;

use TYPO3\CMS\Core\Exception\SiteNotFoundException;
use TYPO3\CMS\Core\Routing\RouterInterface;
use TYPO3\CMS\Core\Site\SiteFinder;

/**
 * Builds absolute links to the detail page of a record, or to any other page.
 *
 * The detail page is resolved per record folder:
 *   1. exact folder match in the grant's mapping
 *   2. nearest parent folder (inherited by subfolders, via rootline)
 *   3. default detail page of the grant (0 = no link)
 *
 * Links are generated by the router of the site the target page belongs to,
 * in that site's default language, so route enhancers, aspects and cHash
 * apply. A target page that anonymous visitors cannot reach (hidden, deleted,
 * access-restricted, outside its publishing dates) or that belongs to no site
 * results in an empty link.
 */
final class DetailLinkBuilder
{
    /** @var array<int, int> */
    private array $detailPids = [];

    /**
     * @param array<int, int> $detailMap storage_pid => detail_pid
     */
    public function __construct(
        private readonly SiteFinder $siteFinder,
        private readonly AnonymousPageAccess $pageAccess,
        private readonly array $detailMap = [],
        private readonly int $defaultDetailPid = 0,
    ) {}

    /**
     * @param int $recordPid Folder of the record
     * @param array<string, mixed> $arguments Plugin arguments of the detail view
     * @return string Absolute URL, or '' without a reachable detail page
     */
    public function build(int $recordPid, array $arguments): string
    {
        return $this->buildPageLink($this->resolveDetailPid($recordPid), $arguments);
    }

    /**
     * @param array<string, mixed> $arguments Query arguments
     * @return string Absolute URL of the page, or '' if it is not reachable
     */
    public function buildPageLink(int $pageId, array $arguments = [], string $fragment = ''): string
    {
        if ($pageId <= 0 || !$this->pageAccess->isPageVisible($pageId)) {
            return '';
        }
        try {
            $site = $this->siteFinder->getSiteByPageId($pageId, $this->pageAccess->getRootline($pageId));
        } catch (SiteNotFoundException) {
            return '';
        }
        return (string)$site->getRouter($this->pageAccess->getContext())->generateUri(
            $pageId,
            ['_language' => $site->getDefaultLanguage()] + $arguments,
            $fragment,
            RouterInterface::ABSOLUTE_URL
        );
    }

    public function resolveDetailPid(int $recordPid): int
    {
        if ($recordPid <= 0) {
            return $this->defaultDetailPid;
        }
        if (array_key_exists($recordPid, $this->detailPids)) {
            return $this->detailPids[$recordPid];
        }
        if ($this->detailMap !== []) {
            // The folder itself comes first in the rootline, then its parents.
            foreach ($this->pageAccess->getRootline($recordPid) ?? [] as $page) {
                $pid = (int)($page['uid'] ?? 0);
                if (isset($this->detailMap[$pid])) {
                    return $this->detailPids[$recordPid] = $this->detailMap[$pid];
                }
            }
        }
        return $this->detailPids[$recordPid] = $this->defaultDetailPid;
    }
}
